function laplacianI(e){const t=e.length;if(t<2)return 1;const n=Array.from({length:t-1},()=>new Array(t-1).fill(0));for(let r=0;r<t-1;r++){let l=0;for(let d=0;d<t;d++)l+=e[r][d];n[r][r]=l;for(let d=0;d<t-1;d++)r!==d&&(n[r][d]=-e[r][d])}const s=n.map(r=>r.slice());let i=1;for(let r=0;r<t-1;r++){let l=r;for(let d=r+1;d<t-1;d++)Math.abs(s[d][r])>Math.abs(s[l][r])&&(l=d);if(Math.abs(s[l][r])<1e-12)return 0;if(l!==r){const d=s[r];s[r]=s[l],s[l]=d,i=-i}i*=s[r][r];for(let d=r+1;d<t-1;d++){const c=s[d][r]/s[r][r];for(let m=r;m<t-1;m++)s[d][m]-=c*s[r][m]}}return Math.round(Math.abs(i))}

function placeCandidatesI(e,t){const n=[],s=e.nodes;if(!s.length)return n;let i=90,r=-90,l=180,d=-180;s.forEach(f=>{i=Math.min(i,f.lat),r=Math.max(r,f.lat),l=Math.min(l,f.lng),d=Math.max(d,f.lng)});const c=Math.max(.01,(r-i)*.15),m=Math.max(.01,(d-l)*.15);i-=c,r+=c,l-=m,d+=m;const h=Math.ceil(Math.sqrt(t));for(let f=0;f<=h;f++)for(let p=0;p<=h;p++)n.push({lat:i+(r-i)*f/h,lng:l+(d-l)*p/h});return n}

