function mlibFn_defaultModelProfile(){return{prop:"auto",fade:"f_lognormal",mimo:"mimo_siso",modcod:"auto",traffic:"none",sim:"none",info:"shannon",targetBer:1e-5,targetAvailPct:99,enabled:!0}}

