function mlibFn_sqrtmSym(e){const t=e.length,n=e.map(r=>r.slice());let s=[];for(let r=0;r<t;r++){s.push([]);for(let l=0;l<t;l++)s[r].push(r===l?1:0)}for(let r=0;r<60;r++){let l=0;for(let d=0;d<t;d++)for(let c=d+1;c<t;c++)l+=n[d][c]*n[d][c];if(l<1e-20)break;for(let d=0;d<t-1;d++)for(let c=d+1;c<t;c++){const m=n[d][c];if(Math.abs(m)<1e-17)continue;const h=(n[c][c]-n[d][d])/(2*m),f=Math.sign(h||1)/(Math.abs(h)+Math.sqrt(h*h+1)),p=1/Math.sqrt(f*f+1),g=f*p;for(let v=0;v<t;v++){const M=n[v][d],w=n[v][c];n[v][d]=p*M-g*w,n[v][c]=g*M+p*w}for(let v=0;v<t;v++){const M=n[d][v],w=n[c][v];n[d][v]=p*M-g*w,n[c][v]=g*M+p*w}for(let v=0;v<t;v++){const M=s[v][d],w=s[v][c];s[v][d]=p*M-g*w,s[v][c]=g*M+p*w}}}const i=[];for(let r=0;r<t;r++){i.push([]);for(let l=0;l<t;l++)i[r].push(0)}for(let r=0;r<t;r++){const l=Math.sqrt(Math.max(0,n[r][r]));for(let d=0;d<t;d++)for(let c=0;c<t;c++)i[d][c]+=s[d][r]*l*s[c][r]}return i}

