var mlibFn_Q = e=>.5*erfcI(e/Math.SQRT2);
var mlibFn_cabs = e=>Math.hypot(e.re,e.im);
var mlibFn_cadd = (e,t)=>({re:e.re+t.re,im:e.im+t.im});
var mlibFn_carg = e=>Math.atan2(e.im,e.re);
var mlibFn_cdiv = (e,t)=>{const n=t.re*t.re+t.im*t.im||1e-30;return{re:(e.re*t.re+e.im*t.im)/n,im:(e.im*t.re-e.re*t.im)/n}};
