var mlibFn_csqrt = e=>{const t=Math.sqrt(cabsI(e)),n=cargI(e)/2;return{re:t*Math.cos(n),im:t*Math.sin(n)}};
var mlibFn_cx = (e,t=0)=>({re:e,im:t});
