/* ===== 5b. Подсистемы воздействий, миссии, угроз и утилит (frozen-неймспейсы оригинала) ===== */
var threatParamI =(e,t,n,s={})=>({id:e,label:t,def:n,...s});

function threatParamNumI(e,t,n){const s=e.params&&e.params[t];return s==null||s===""||!isFinite(+s)?n:+s}

function nodeNameI(e,t){const n=e.nodes.find(s=>s.id===t);return n?n.name||n.id:t}

function nodeByIdI(e,t){return e.nodes.find(n=>n.id===t)||null}

function midpointI(e,t){return{lat:(e.lat+t.lat)/2,lng:(e.lng+t.lng)/2}}

function offsetPointI(e,t,n,s){const i=n*Math.PI/180,r=Math.cos(i)*s,l=Math.sin(i)*s;return{lat:e+r/110.574,lng:t+l/(111.32*Math.cos(e*Math.PI/180))}}

function bearingToI(e,t){const n=(t.lng-e.lng)*Math.cos(e.lat*Math.PI/180),s=t.lat-e.lat;return(Math.atan2(n,s)*180/Math.PI+360)%360}

function distToSegmentKmI(e,t,n){const s=Math.cos(e.lat*Math.PI/180),i=e.lng*s,r=e.lat,l=t.lng*s,d=t.lat,c=n.lng*s,m=n.lat,h=c-l,f=m-d,p=h*h+f*f;let g=p>0?((i-l)*h+(r-d)*f)/p:0;g=clamp(g,0,1);const v=l+g*h,M=d+g*f;return Math.sqrt((i-v)*(i-v)+(r-M)*(r-M))*111.32}

function losBlockedI(e,t,n,s=1.5,i=1.5,r=24){const l=TERR6.elev(t.lat,t.lng,e),d=TERR6.elev(n.lat,n.lng,e);for(let c=1;c<r;c++){const m=c/r,h=t.lat+(n.lat-t.lat)*m,f=t.lng+(n.lng-t.lng)*m,p=l+s+(d+i-l-s)*m;if(TERR6.elev(h,f,e)>p)return!0}return!1}

