/* ===== 9. Реестр моделей: внутренние функции ===== */
function numInputDecl(e,t,n,s={}){return{id:e,label:t,type:"num",def:n,...s}}

function modelByIdI(e){return e?MODEL_MAP_I[e]:void 0}

function modelsByGroupI(e){return ALL_MODELS_I.filter(t=>t.group===e)}

function modelsByStageI(e){return ALL_MODELS_I.filter(t=>t.stage===e)}

